CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE app_user (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(320) NOT NULL,
 password_hash TEXT, display_name VARCHAR(160) NOT NULL, preferred_language VARCHAR(10) NOT NULL DEFAULT 'bn',
 status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE', email_verified BOOLEAN NOT NULL DEFAULT FALSE,
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 CHECK(status IN ('PENDING','ACTIVE','SUSPENDED','DISABLED')), CHECK(preferred_language IN ('bn','en')));
CREATE UNIQUE INDEX uq_user_email_ci ON app_user(lower(email));

CREATE TABLE role(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE permission(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),code VARCHAR(100) UNIQUE NOT NULL,name VARCHAR(160) NOT NULL);
CREATE TABLE user_role(user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,role_id UUID NOT NULL REFERENCES role(id) ON DELETE RESTRICT,PRIMARY KEY(user_id,role_id));
CREATE TABLE role_permission(role_id UUID NOT NULL REFERENCES role(id) ON DELETE CASCADE,permission_id UUID NOT NULL REFERENCES permission(id) ON DELETE RESTRICT,PRIMARY KEY(role_id,permission_id));
CREATE TABLE device(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,device_name VARCHAR(120),platform VARCHAR(20) NOT NULL,app_version VARCHAR(40),last_seen_at TIMESTAMPTZ,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(platform IN ('ANDROID','WEB','OTHER')),CHECK(status IN ('ACTIVE','REVOKED')));
CREATE INDEX ix_device_user_status ON device(user_id,status);

CREATE TABLE language(code VARCHAR(10) PRIMARY KEY,name VARCHAR(80) NOT NULL);
CREATE TABLE subject(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(160) NOT NULL,display_order INT NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE subject_translation(subject_id UUID NOT NULL REFERENCES subject(id) ON DELETE CASCADE,language_code VARCHAR(10) NOT NULL REFERENCES language(code) ON DELETE RESTRICT,name VARCHAR(160) NOT NULL,PRIMARY KEY(subject_id,language_code));
CREATE TABLE paper(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),subject_id UUID NOT NULL REFERENCES subject(id) ON DELETE RESTRICT,code VARCHAR(30) NOT NULL,name VARCHAR(160) NOT NULL,paper_number SMALLINT,display_order INT NOT NULL DEFAULT 0,UNIQUE(subject_id,code));
CREATE TABLE book(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),subject_id UUID NOT NULL REFERENCES subject(id) ON DELETE RESTRICT,title VARCHAR(240) NOT NULL,publisher VARCHAR(160),isbn VARCHAR(30),metadata JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE book_edition(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),book_id UUID NOT NULL REFERENCES book(id) ON DELETE CASCADE,edition_label VARCHAR(80) NOT NULL,publication_year SMALLINT,UNIQUE(book_id,edition_label));
CREATE TABLE chapter(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),paper_id UUID NOT NULL REFERENCES paper(id) ON DELETE RESTRICT,code VARCHAR(40) NOT NULL,title VARCHAR(200) NOT NULL,display_order INT NOT NULL DEFAULT 0,UNIQUE(paper_id,code));
CREATE TABLE topic(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),chapter_id UUID NOT NULL REFERENCES chapter(id) ON DELETE CASCADE,code VARCHAR(40) NOT NULL,title VARCHAR(200) NOT NULL,display_order INT NOT NULL DEFAULT 0,UNIQUE(chapter_id,code));

CREATE TABLE question(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),chapter_id UUID NOT NULL REFERENCES chapter(id) ON DELETE RESTRICT,question_type VARCHAR(20) NOT NULL,difficulty VARCHAR(20),status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',current_version_id UUID,created_by UUID REFERENCES app_user(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(question_type IN ('MCQ','CQ','NUMERICAL','SHORT','OTHER')),CHECK(status IN ('DRAFT','IN_REVIEW','APPROVED','PUBLISHED','ARCHIVED')));
CREATE TABLE question_version(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),question_id UUID NOT NULL REFERENCES question(id) ON DELETE CASCADE,version_no INT NOT NULL,language_code VARCHAR(10) NOT NULL REFERENCES language(code) ON DELETE RESTRICT,stem TEXT NOT NULL,marks NUMERIC(7,2),metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_by UUID REFERENCES app_user(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(question_id,version_no,language_code),CHECK(marks IS NULL OR marks>=0));
ALTER TABLE question ADD CONSTRAINT fk_question_current_version FOREIGN KEY(current_version_id) REFERENCES question_version(id) ON DELETE SET NULL;

CREATE TABLE solution(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),question_id UUID NOT NULL REFERENCES question(id) ON DELETE CASCADE,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',current_version_id UUID,created_by UUID REFERENCES app_user(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(question_id),CHECK(status IN ('DRAFT','IN_REVIEW','APPROVED','PUBLISHED','ARCHIVED')));
CREATE TABLE solution_version(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),solution_id UUID NOT NULL REFERENCES solution(id) ON DELETE CASCADE,version_no INT NOT NULL,language_code VARCHAR(10) NOT NULL REFERENCES language(code) ON DELETE RESTRICT,summary TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_by UUID REFERENCES app_user(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(solution_id,version_no,language_code));
ALTER TABLE solution ADD CONSTRAINT fk_solution_current_version FOREIGN KEY(current_version_id) REFERENCES solution_version(id) ON DELETE SET NULL;
CREATE TABLE solution_step(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),solution_version_id UUID NOT NULL REFERENCES solution_version(id) ON DELETE CASCADE,step_no INT NOT NULL,title VARCHAR(200),body TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,UNIQUE(solution_version_id,step_no),CHECK(step_no>0));

CREATE TABLE mcq_option(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),question_version_id UUID NOT NULL REFERENCES question_version(id) ON DELETE CASCADE,option_key VARCHAR(5) NOT NULL,option_text TEXT NOT NULL,is_correct BOOLEAN NOT NULL DEFAULT FALSE,display_order INT NOT NULL DEFAULT 0,UNIQUE(question_version_id,option_key),UNIQUE(question_version_id,display_order));
CREATE TABLE mcq_explanation(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),question_version_id UUID NOT NULL REFERENCES question_version(id) ON DELETE CASCADE,language_code VARCHAR(10) NOT NULL REFERENCES language(code) ON DELETE RESTRICT,explanation TEXT NOT NULL,UNIQUE(question_version_id,language_code));
CREATE TABLE tag(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),code VARCHAR(80) UNIQUE NOT NULL,label VARCHAR(120) NOT NULL);
CREATE TABLE question_tag(question_version_id UUID NOT NULL REFERENCES question_version(id) ON DELETE CASCADE,tag_id UUID NOT NULL REFERENCES tag(id) ON DELETE RESTRICT,PRIMARY KEY(question_version_id,tag_id));

CREATE TABLE media_asset(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),storage_key TEXT UNIQUE NOT NULL,mime_type VARCHAR(120) NOT NULL,file_name VARCHAR(255) NOT NULL,byte_size BIGINT NOT NULL,checksum_sha256 CHAR(64) NOT NULL,width INT,height INT,alt_text VARCHAR(500),caption TEXT,created_by UUID REFERENCES app_user(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(byte_size>0));
CREATE TABLE question_media_attachment(question_version_id UUID NOT NULL REFERENCES question_version(id) ON DELETE CASCADE,media_asset_id UUID NOT NULL REFERENCES media_asset(id) ON DELETE RESTRICT,display_order INT NOT NULL,attachment_role VARCHAR(30) NOT NULL DEFAULT 'ILLUSTRATION',PRIMARY KEY(question_version_id,media_asset_id),UNIQUE(question_version_id,display_order),CHECK(display_order>=0));
CREATE TABLE solution_step_media_attachment(solution_step_id UUID NOT NULL REFERENCES solution_step(id) ON DELETE CASCADE,media_asset_id UUID NOT NULL REFERENCES media_asset(id) ON DELETE RESTRICT,display_order INT NOT NULL,attachment_role VARCHAR(30) NOT NULL DEFAULT 'ILLUSTRATION',PRIMARY KEY(solution_step_id,media_asset_id),UNIQUE(solution_step_id,display_order),CHECK(display_order>=0));

CREATE TABLE import_job(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),source_type VARCHAR(20) NOT NULL,file_name VARCHAR(255),status VARCHAR(24) NOT NULL DEFAULT 'STAGED',requested_by UUID REFERENCES app_user(id) ON DELETE SET NULL,total_rows INT NOT NULL DEFAULT 0,success_rows INT NOT NULL DEFAULT 0,error_rows INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(source_type IN ('JSON','CSV','XLSX','ZIP')));
CREATE TABLE import_row(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),import_job_id UUID NOT NULL REFERENCES import_job(id) ON DELETE CASCADE,row_no INT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',payload JSONB NOT NULL DEFAULT '{}'::jsonb,UNIQUE(import_job_id,row_no));
CREATE TABLE import_error(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),import_row_id UUID NOT NULL REFERENCES import_row(id) ON DELETE CASCADE,field_name VARCHAR(120),error_code VARCHAR(80) NOT NULL,message TEXT NOT NULL);
CREATE TABLE review_task(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),entity_type VARCHAR(40) NOT NULL,entity_id UUID NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',assigned_to UUID REFERENCES app_user(id) ON DELETE SET NULL,reviewer_note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),resolved_at TIMESTAMPTZ);
CREATE TABLE audit_log(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_user_id UUID REFERENCES app_user(id) ON DELETE SET NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id UUID,correlation_id VARCHAR(100),before_data JSONB,after_data JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());

CREATE TABLE plan(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),code VARCHAR(60) UNIQUE NOT NULL,name VARCHAR(160) NOT NULL,price_minor BIGINT NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'BDT',duration_days INT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,CHECK(price_minor>=0),CHECK(duration_days>0));
CREATE TABLE customer_order(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT,plan_id UUID NOT NULL REFERENCES plan(id) ON DELETE RESTRICT,order_code VARCHAR(80) UNIQUE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',amount_minor BIGINT NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'BDT',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(amount_minor>=0));
CREATE TABLE payment(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID NOT NULL REFERENCES customer_order(id) ON DELETE RESTRICT,provider VARCHAR(40) NOT NULL,provider_payment_id VARCHAR(160),status VARCHAR(20) NOT NULL DEFAULT 'INITIATED',amount_minor BIGINT NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'BDT',paid_at TIMESTAMPTZ,raw_response JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX uq_payment_provider_ref ON payment(provider,provider_payment_id) WHERE provider_payment_id IS NOT NULL;
CREATE TABLE subscription(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT,order_id UUID NOT NULL REFERENCES customer_order(id) ON DELETE RESTRICT,plan_id UUID NOT NULL REFERENCES plan(id) ON DELETE RESTRICT,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE TABLE entitlement(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),subscription_id UUID NOT NULL REFERENCES subscription(id) ON DELETE CASCADE,resource_type VARCHAR(40) NOT NULL,resource_id UUID,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,CHECK(ends_at>starts_at));

CREATE TABLE bookmark(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,question_id UUID NOT NULL REFERENCES question(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,question_id));
CREATE TABLE learning_history(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,question_id UUID REFERENCES question(id) ON DELETE SET NULL,event_type VARCHAR(40) NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),metadata JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE offline_manifest(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version_no BIGINT NOT NULL,scope_type VARCHAR(30) NOT NULL,scope_id UUID,checksum_sha256 CHAR(64) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'READY',generated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(scope_type,scope_id,version_no));
CREATE TABLE offline_manifest_item(manifest_id UUID NOT NULL REFERENCES offline_manifest(id) ON DELETE CASCADE,resource_type VARCHAR(40) NOT NULL,resource_id UUID NOT NULL,resource_version BIGINT NOT NULL,media_asset_id UUID REFERENCES media_asset(id) ON DELETE RESTRICT,checksum_sha256 CHAR(64),PRIMARY KEY(manifest_id,resource_type,resource_id));
CREATE TABLE analytics_event(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES app_user(id) ON DELETE SET NULL,event_name VARCHAR(100) NOT NULL,event_time TIMESTAMPTZ NOT NULL DEFAULT now(),correlation_id VARCHAR(100),properties JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE idempotency_record(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),scope VARCHAR(80) NOT NULL,idempotency_key VARCHAR(160) NOT NULL,request_hash CHAR(64) NOT NULL,response_status INT,response_body JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),expires_at TIMESTAMPTZ,UNIQUE(scope,idempotency_key));
CREATE TABLE webhook_event(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),provider VARCHAR(40) NOT NULL,provider_event_id VARCHAR(200) NOT NULL,event_type VARCHAR(100),signature_verified BOOLEAN NOT NULL DEFAULT FALSE,processed_at TIMESTAMPTZ,status VARCHAR(20) NOT NULL DEFAULT 'RECEIVED',payload JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(provider,provider_event_id));

