INSERT INTO role(code,name) VALUES ('SUPER_ADMIN','Super Admin'),('ADMIN','Admin'),('CONTENT_EDITOR','Content Editor'),('MODERATOR','Moderator'),('TEACHER_REVIEWER','Teacher/Reviewer'),('SUPPORT','Support'),('ANALYST','Analyst') ON CONFLICT DO NOTHING;
